import { icon,logo } from './icons.js';
import { robotArt,partArt } from './art.js';
import { mountViewer } from './viewer.js';
import { mountWiring } from './wiring.js';
import { mountAssembly } from './assembly.js';
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let session,projects=[],project=null,partId='fl_motor_mount',page='home',tab='Parts',detail=true,mode='Edit',query='',filter='ALL',sending=false,readOnly=false,disposeViewer=null;
const app=$('#app'),modal=$('#modal');
let modalViewerDispose=null;
const tag=p=>`<span class="tag ${p.category.toLowerCase()}">${icon(p.category==='3D PRINT'?'cube':p.category==='POWER'?'bolt':'parts')}${esc(p.category)}</span>`;
const btn=(action,label,cls='',ico='')=>`<button data-action="${action}" class="btn ${cls}">${ico?icon(ico):''}${label}</button>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
async function api(url,options={}){const response=await fetch('/api'+url,{...options,headers:{'Content-Type':'application/json',...options.headers},body:options.body===undefined?undefined:JSON.stringify(options.body)});const data=await response.json();if(!response.ok)throw new Error(data.error||`Request failed (${response.status})`);return data;}
async function mutate(action,body={},method='POST'){if(readOnly)throw new Error('Shared projects are read-only');const updated=await api(`/projects/${project.id}/${action}`,{method,body:{...body,version:project.version}});project=updated;await refreshProjects();return updated;}
async function refreshProjects(){projects=await api('/projects');}
function currentPart(){return project?.parts.find(p=>p.id===partId)||project?.parts[0];}
const cost=()=>project.parts.reduce((sum,p)=>sum+p.quantity*p.cost,0);
function closeModal(){modalViewerDispose?.();modalViewerDispose=null;modal.close();modal.innerHTML='';modal.className='';}
function showModal(title,body,cls=''){modal.className=cls;modal.innerHTML=`<div class="modal-heading"><h2>${title}</h2><button class="plain" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${body}`;if(!modal.open)modal.showModal();}
const errorInModal=e=>{let el=$('.modal-error',modal);if(!el){el=document.createElement('p');el.className='modal-error';modal.append(el);}el.textContent=e.message;};
function sidebar(){return `<aside class="sidebar"><div class="sidebar-brand">${logo()}<span class="wordmark">BLUE DESIGN</span><button class="plain" data-action="home" aria-label="Home">${icon('collapse')}</button></div><button class="profile" data-action="profile"><span class="avatar"></span><span class="profile-copy"><b>${esc(session.profile.name)}</b><span>${esc(session.profile.email||'Local account')}</span></span>${icon('down')}</button><nav class="side-nav">${[['home','home','Home'],['community','globe','Community'],['projects','folder','Projects']].map(([action,i,label])=>`<button data-action="${action}" class="${page===action?'active':''}">${icon(i)}${label}</button>`).join('')}</nav><div class="recent"><div class="recent-label">RECENT ${icon('down')}</div>${projects.slice(0,8).map(p=>`<button class="recent-project" data-project="${p.id}"><span class="recent-thumb">${partArt({category:'STRUCTURE'})}</span><span><b>${esc(p.name)}</b><small>${p.parts} parts</small></span></button>`).join('')}</div><div class="sidebar-footer"><button class="side-action" data-action="mcp-connect">${icon('link')}Connect MCP</button><button class="side-action" data-action="settings">${icon('settings')}Workspace Settings</button><button class="side-action" data-action="about">${icon('code')}Open Source / About</button><div class="version">BLUE DESIGN · LOCAL · v1.0</div></div></aside>`;}
function home(){disposeViewer?.();disposeViewer=null;readOnly=false;page='home';project=null;history.replaceState(null,'','/');app.innerHTML=`<div class="home-shell">${sidebar()}<main class="home-main draft-grid"><div class="home-top"><span class="local-label"><i></i> YOUR IDEAS. YOUR WORKSPACE.</span><button class="plain" data-action="new-project">${icon('plus')} NEW PROJECT</button></div><section class="hero"><div class="hero-art">${robotArt()}</div><h1 class="hero-wordmark">BLUE DESIGN</h1><form class="hero-prompt" id="create-prompt"><textarea name="idea" aria-label="Describe your hardware idea" placeholder="Ask Blue Design to design anything…" required maxlength="5000"></textarea><div class="prompt-tools"><button type="button" data-action="ideas" title="Project ideas">${icon('bulb')}</button><button type="button" data-action="upload" title="Upload an image, document, or BOM">${icon('image')}</button><button type="button" data-action="new-project" title="Start a blank design">${icon('edit')}</button><button type="button" class="model-select" data-action="models">${esc(session.label||'Local commands')} ${icon('down')}</button><button class="hero-send" aria-label="Create project">${icon('send')}</button></div></form><div class="hero-bottom"><button data-action="idea-robot">Autonomous service robot ↗</button><button data-action="idea-mount">Custom motor mount ↗</button><button data-action="upload">Upload your content ↗</button></div></section><section class="home-project-strip"><div class="strip-label">[ YOUR WORKBENCH ]<button data-action="projects">ALL PROJECTS ↗</button></div><div class="mini-projects">${projects.slice(0,3).map(p=>`<button class="mini-card" data-project="${p.id}">${partArt({category:'STRUCTURE'})}<span><b>${esc(p.name)}</b><small>${p.parts} COMPONENTS · OPEN PROJECT ↗</small></span></button>`).join('')}${!projects.length?'<p>Your first idea starts here.</p>':''}</div></section></main></div>`;}
async function collection(which){disposeViewer?.();disposeViewer=null;page=which;readOnly=false;project=null;history.replaceState(null,'','/');let entries=projects;if(which==='community')entries=await api('/community');app.innerHTML=`<div class="home-shell">${sidebar()}<main class="collection"><div class="collection-header"><div><div class="eyebrow">YOUR OPEN HARDWARE WORKSPACE</div><h1>${which==='community'?'COMMUNITY PROJECTS':'YOUR PROJECTS'}</h1><p>${which==='community'?'Published snapshots from this installation. Fork an idea and make it your own.':'A home for every idea, from the first sketch to the final part.'}</p></div>${btn('new-project','NEW PROJECT','white','plus')}</div><div class="project-grid">${entries.map(p=>`<button class="project-card" ${p.token?`data-shared="${p.token}"`:`data-project="${p.id}"`}><div class="project-visual">${robotArt()}</div><div class="project-card-copy"><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><small>UPDATED ${new Date(p.updatedAt).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</small><div class="project-card-footer"><span>${p.parts} parts</span><span>${p.token?'VIEW SNAPSHOT':'OPEN PROJECT'} ↗</span></div></div></button>`).join('')}</div>${!entries.length?`<div class="empty">${icon('globe')}<h2>No published projects yet</h2><p>Publish a project from its workspace to add a read-only snapshot here.</p>${btn('projects','GO TO PROJECTS','','folder')}</div>`:''}</main></div>`;}
async function openProject(id){project=await api(`/projects/${id}`);page='editor';readOnly=false;partId=project.parts[0]?.id;tab='Parts';detail=true;query='';filter='ALL';history.replaceState(null,'',`/?project=${id}`);renderEditor();}
async function openShared(token){project=await api(`/shared/${token}`);readOnly=true;page='editor';tab='Parts';detail=true;partId=project.parts[0]?.id;history.replaceState(null,'',`/shared/${token}`);renderEditor();}
function renderEditor(){disposeViewer?.();disposeViewer=null;const p=currentPart();app.innerHTML=`<div class="editor">${readOnly?'<div class="readonly-banner">Read-only published snapshot · private chat is excluded <a href="/">Open your workspace ↗</a></div>':''}<header class="editor-header"><div class="project-brand"><button data-action="home" aria-label="Back to home">${logo()}</button><h1>${esc(project.name.toUpperCase())}</h1></div><button class="icon-btn" data-action="history" title="Project history">${icon('history')}</button><nav class="editor-tabs">${[['Info','info'],['Parts','parts'],['Wiring','wiring'],['Mech','mech'],['Instructions','file']].map(([name,i])=>`<button data-tab="${name}" class="${tab===name?'active':''}">${icon(i)}${name.toUpperCase()}${name==='Info'?'<i class="status-dot amber"></i>':name==='Wiring'?'<i class="status-dot"></i>':''}</button>`).join('')}</nav><div class="editor-actions">${!readOnly?`<button class="icon-btn" data-action="mcp-connect" title="Connect MCP">${icon('link')}</button>`:''}<button class="icon-btn" data-action="export" title="Export project">${icon('download')}</button>${btn(readOnly?'fork':'share',readOnly?'FORK':'SHARE','blue',readOnly?'copy':'users')}${!readOnly?btn('publish',project.published?'PUBLISHED':'PUBLISH','green','globe'):''}<button class="avatar" data-action="settings" aria-label="Workspace settings"></button></div></header><div class="editor-body"><aside class="chat-panel"><div class="panel-title"><span>${icon('chat')} CHAT</span><div class="panel-tools"><button data-action="history" title="Design history">${icon('undo')}</button><button data-action="collapse-chat" title="Collapse chat">${icon('collapse')}</button><button data-action="clear-chat" title="Clear conversation">${icon('trash')}</button></div></div><div class="messages" id="messages">${renderMessages()}</div><div class="chat-bottom"><div class="suggest-label">SUGGESTIONS<button data-action="toggle-suggestions" aria-label="Toggle suggestions">${icon('down')}</button></div><div class="suggestions"><button data-suggest="Integrate touch-based human-robot interaction capabilities"><small>+</small>Integrate touch-based human-robot interaction capabilities</button><button data-suggest="Upgrade to a high-capacity battery for longer operation"><small>~</small>Upgrade to high-capacity battery for longer operation</button><button data-suggest="Combine motor control and logic into one"><small>−</small>Combine motor control and logic into one</button></div><form class="chat-form" id="chat-form"><textarea name="text" id="chat-input" aria-label="Describe a design change or ask a question" placeholder="> Describe a change to apply…" maxlength="8000" ${readOnly?'disabled':''}></textarea><div class="chat-form-bottom"><div class="mode-toggle"><button type="button" data-mode="Edit" class="${mode==='Edit'?'active':''}">${icon('edit')} EDIT</button><button type="button" data-mode="Ask" class="${mode==='Ask'?'active':''}">${icon('chat')} ASK</button></div><button type="button" class="plain" data-action="upload" title="Upload source content">${icon('image')}</button><button type="button" class="plain" data-action="edit-part" title="Edit selected component">${icon('edit')}</button><button type="button" class="model-select" data-action="models">${esc(session.label||'Local commands')} ${icon('down')}</button><button class="chat-send" aria-label="Send message" ${readOnly||sending?'disabled':''}>${icon('send')}</button></div></form><div class="save-line"><span>${icon('check')} ${readOnly?'Published snapshot':'Saved to your machine'}</span><button data-action="settings">${esc(session.provider==='local'?'Local commands':'Connected AI')} · Settings</button></div></div></aside><main class="workspace"><div class="workspace-bar"><button data-action="back-parts">${icon('arrow')}${tab==='Parts'&&detail?'BACK TO PARTS':tab.toUpperCase()}</button><span>${readOnly?'SHARED SNAPSHOT':`V${project.version} · LOCAL WORKSPACE`}</span></div><div class="workspace-content" id="content">${tabContent(p)}</div></main></div></div>`;if(tab==='Info')$('.chat-panel').innerHTML=aboutSidebar();if(tab==='Wiring'||tab==='Mech')mountEngineering();if(project.messages.length>1){const messages=$('#messages');if(messages)messages.scrollTop=messages.scrollHeight;}}
function formatMessage(text){return esc(text).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>');}
function workflowPending(){return `<section class="workflow-progress"><div class="workflow-label"><span class="spinner"></span> RUNNING DESIGN WORKFLOW</div><p>Planning executable changes with ${esc(session.label||session.provider)}. The project will save after validation.</p><div class="workflow-pending-stages"><span class="active">1 · Plan changes</span><span>2 · Validate parts & connections</span><span>3 · Sync wiring & assembly</span><span>4 · Save build instructions</span></div></section>`;}
function workflowCard(){const w=project.workflow;if(!w)return '';return `<section class="workflow-result"><div class="workflow-label">${icon('check')} DESIGN WORKFLOW COMPLETED</div><p>${esc(w.summary)}</p><div class="workflow-stages">${w.stages.map(s=>`<button data-workflow-tab="${esc(s.name)}">${icon('check')}<span><b>${esc(s.name)}</b><small>${esc(s.detail)}</small></span>${icon('external')}</button>`).join('')}</div><small class="workflow-at">Saved ${new Date(w.at).toLocaleString()} · ${esc(w.provider)}</small></section>`;}
function renderMessages(){if(!project.messages.length)return `<div class="chat-empty">${readOnly?'Private design conversations are excluded from shared projects.':'Ask a question or edit your design.'}</div>`;return project.messages.map(m=>`<article class="message ${m.role==='user'?'user':''}">${project.messages.length>1?`<div class="message-meta"><span>${m.role==='user'?'YOU':`BLUE DESIGN · ${esc(m.provider||'DESIGN ASSISTANT').toUpperCase()}`}</span></div>`:''}${formatMessage(m.text)}</article>${m.workflowId&&m.workflowId===project.workflow?.id?workflowCard():''}`).join('')+(sending?'<div class="thinking">Working on your design…</div>':'');}
function tabContent(p){if(tab==='Parts')return detail&&p?partDetail(p):partsList();if(tab==='Info')return infoView();if(tab==='Wiring')return wiringView();if(tab==='Mech')return mechView(p);return instructionsView();}
function partDetail(p){const targets=p.connections.map(id=>project.parts.find(x=>x.id===id)).filter(Boolean);const rows=Object.entries(p.specs);return `<article class="part-detail"><div class="part-header"><div class="part-image"><small>BLUE DESIGN</small>${partArt(p)}<span class="image-code">COMPONENT / ${String(project.parts.indexOf(p)+1).padStart(2,'0')}</span></div><div class="part-heading"><div class="part-heading-actions">${!readOnly?`<button class="edit-part" data-action="edit-part" title="Edit component">${icon('edit')}</button><button data-action="delete-part" title="Delete component">${icon('trash')}</button>`:''}</div><h1>${esc(p.name.toUpperCase())}</h1>${tag(p)}<p>${esc(p.description)}</p>${p.geometry?btn('cad','GENERATE CAD <small class="beta">BETA</small>','orange','cube'):btn('edit-part',readOnly?'COMPONENT SPECIFICATIONS':'EDIT COMPONENT','','edit')}</div></div><div class="part-sections"><details open><summary>${icon('chevron')}<i class="section-dot"></i>TECHNICAL SPECIFICATIONS</summary><p class="part-description">${esc(p.longDescription||p.description)}</p><dl class="spec-grid">${rows.map(([k,v])=>`<div class="spec-row"><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}${!rows.length?'<div class="muted">No specifications yet. Edit this component to add them.</div>':''}</dl></details><details open><summary>${icon('chevron')}<i class="section-dot"></i>CONNECTIONS</summary>${targets.length?`<div class="connection-graph" style="min-height:${Math.max(70,targets.length*83-18)}px"><svg class="connection-lines" viewBox="0 0 1000 ${Math.max(70,targets.length*83-18)}" preserveAspectRatio="none" aria-hidden="true">${targets.map((_,i)=>`<path d="M220 24 C370 24 380 ${i*83+30} 600 ${i*83+30}" fill="none" stroke="#ddd" stroke-width="1.2"/>`).join('')}</svg><div class="connection-node connection-source">${esc(p.name.toUpperCase())}</div><div class="connection-targets">${targets.map(x=>`<button class="connection-node" data-part="${x.id}">${esc(x.name.toUpperCase())}<small>${esc(x.description)}</small></button>`).join('')}</div></div>`:'<p class="detail-copy">No connections yet. Add connections in Edit component.</p>'}</details><details><summary>${icon('chevron')}<i class="section-dot"></i>MATERIAL SELECTION</summary><p class="detail-copy">${esc(p.material||p.specs.Material||p.specs['Recommended Material']||'Material has not been specified. Add it in the component editor.')}</p></details><details><summary>${icon('chevron')}<i class="section-dot"></i>DESIGN TIPS & TOLERANCES</summary><p class="detail-copy">${esc(p.tips||'Check the manufacturer’s drawing and validate prototype fit before assembly.')}</p></details><details><summary>${icon('chevron')}<i class="section-dot"></i>CAD / 3D FILES</summary>${p.geometry?`<div class="file-row">${icon('cube')}<span><b>${esc(p.name)}.scad</b><small>Editable parametric CAD · mm</small></span>${btn('download-scad','DOWNLOAD','','download')}</div><div class="file-row">${icon('cube')}<span><b>${esc(p.name)}.stl</b><small>Triangulated bracket · round motor opening</small></span>${btn('download-stl','DOWNLOAD','','download')}</div>`:'<p class="detail-copy">No parametric geometry is assigned to this component.</p>'}</details><div class="component-id">COMPONENT ID<span>${esc(p.id)}</span></div></div></article>`;}
function partsList(){const list=project.parts.filter(p=>(filter==='ALL'||p.category===filter)&&`${p.name} ${p.description}`.toLowerCase().includes(query.toLowerCase()));return `<div class="page-top"><div><div class="eyebrow">BILL OF MATERIALS / ${project.parts.length} COMPONENTS</div><h1>PARTS</h1><p>Every component. Every connection. One place.</p></div><div class="page-tools"><label class="search-box">${icon('search')}<input id="part-search" placeholder="Search parts…" value="${esc(query)}" aria-label="Search parts"></label>${!readOnly?btn('add-part','ADD PART','white','plus'):''}</div></div><div class="filter-row">${['ALL','3D PRINT','STRUCTURE','ELECTRONICS','HARDWARE','SENSOR','POWER'].map(f=>`<button data-filter="${f}" class="${filter===f?'active':''}">${f}</button>`).join('')}</div><div class="part-grid">${list.map(p=>`<button class="part-tile" data-part="${p.id}"><div class="tile-image"><span class="tile-number">${String(project.parts.indexOf(p)+1).padStart(2,'0')} / ${String(project.parts.length).padStart(2,'0')}</span>${partArt(p)}</div><div class="tile-copy">${tag(p)}<h3>${esc(p.name.toUpperCase())}</h3><p>${esc(p.description)}</p><div class="tile-meta"><span>QTY ${p.quantity}</span><span>${p.cost>0?'$'+(p.cost*p.quantity).toFixed(2):'COST TBD'} ↗</span></div></div></button>`).join('')}</div>${!list.length?'<div class="empty">No components match your search.</div>':''}`;}
function wiringView(){return '<div id="engineering-root"><div class="empty"><span class="spinner"></span> Opening wiring workspace…</div></div>';}
function mechView(){return '<div id="engineering-root"><div class="empty"><span class="spinner"></span> Opening mechanical workspace…</div></div>';}
function instructionsView(){const complete=project.instructions.filter(s=>s.done).length,groups=['Fabricate','Wire','Bring-up','Assemble'];const groupFor=s=>s.group||( /print|fabricat|prepare/i.test(s.title)?'Fabricate':/wire|connect|power/i.test(s.title)?'Wire':/test|validat|verif/i.test(s.title)?'Bring-up':'Assemble');const tools=[...new Set(project.instructions.flatMap(s=>s.tools||[]))];const required=tools.length?tools:['3D printer (material compatible)','Soldering iron with fine tip','Multimeter','Hex key set','Wire strippers and crimping tool','Heat gun','Drill and bits'];return `<div class="guide-header"><span>${icon('file')} INSTRUCTIONS <small>${complete}/${project.instructions.length} DONE</small></span><div>${!readOnly?btn('regenerate-guide','REGENERATE','','mech')+btn('edit-instructions','EDIT','','edit'):''}</div></div><div class="build-guide"><section class="tools-assumptions"><h3>${icon('settings')} TOOLS & ASSUMPTIONS</h3><div class="tools-columns"><div><h4>TOOLS</h4>${required.map(t=>`<p>${icon(/print/i.test(t)?'cube':'settings')}${esc(t)}</p>`).join('')}</div><div><h4>ASSUMPTIONS TO CONFIRM</h4><ul>${(project.workflow?.assumptions?.length?project.workflow.assumptions:['Confirm component datasheets, pin assignments, power ratings and physical fit before building.']).map(a=>`<li>${esc(a)}</li>`).join('')}</ul></div></div></section>${groups.map((group,gi)=>{const steps=project.instructions.filter(s=>groupFor(s)===group);if(!steps.length)return '';return `<section class="guide-group"><header><span><b>${gi+1}.</b>${icon(group==='Wire'?'wiring':group==='Bring-up'?'chip':'settings')}${group}</span><span class="group-progress">${steps.filter(s=>s.done).length}/${steps.length}</span><button class="group-check ${steps.every(s=>s.done)?'checked':''}" data-group-check="${group}" aria-label="Toggle ${group} completion">${steps.every(s=>s.done)?icon('check'):''}</button></header>${steps.map((step,i)=>{const matches=step.partIds?step.partIds.map(id=>project.parts.find(p=>p.id===id)).filter(Boolean):[];return `<article class="guide-step ${step.done?'done':''}"><div class="guide-step-title"><span>${gi+1}.${i+1}</span><input type="checkbox" data-step="${step.id}" ${step.done?'checked':''} ${readOnly?'disabled':''} aria-label="Complete ${esc(step.title)}"><h3>${esc(step.title)}</h3></div><div class="tool-chips">${(step.tools||[]).map((t,j)=>`<span class="tool-chip color-${j%4}">${icon(/print/i.test(t)?'cube':'settings')}${esc(t)}</span>`).join('')}</div>${matches.length?`<div class="guide-parts">${matches.map(p=>`<button class="guide-part" data-part="${p.id}"><span class="guide-part-thumb">${partArt(p)}</span><span><b>${esc(p.name)}</b><small>${esc(p.category)}</small></span></button>`).join('')}</div>`:''}<details class="step-more"><summary>More details ${icon('chevron')}</summary><p>${esc(step.body)}</p></details></article>`;}).join('')}</section>`;}).join('')}${!project.instructions.length?`<div class="empty">Generate a build guide from your components, or write your own instructions.</div>`:''}</div>`;}

function partEditor(add=false){if(readOnly){toast('Fork this project to edit it.');return;}const p=add?{name:'',category:'HARDWARE',quantity:1,cost:0,description:'',specs:{},connections:[],material:'',tips:''}:currentPart();if(!p)return;showModal(add?'ADD COMPONENT':'EDIT COMPONENT',`<form class="modal-form" id="part-form" data-add="${add}"><label>Component name</label><input name="name" maxlength="100" value="${esc(p.name)}" required><div class="form-grid"><div><label>Category</label><select name="category">${['3D PRINT','STRUCTURE','ELECTRONICS','HARDWARE','SENSOR','POWER'].map(c=>`<option ${c===p.category?'selected':''}>${c}</option>`).join('')}</select></div><div><label>Quantity</label><input name="quantity" type="number" min="1" max="10000" step="1" value="${p.quantity}" required></div></div><label>Description</label><textarea name="description" rows="2" maxlength="5000">${esc(p.description)}</textarea><div class="form-grid"><div><label>Unit cost (USD)</label><input name="cost" type="number" min="0" step="0.01" value="${p.cost}" required></div><div><label>Geometry</label><select name="geometry"><option value="none">No parametric model</option value="bracket" ${p.geometry?'selected':''}>Motor bracket</option></select></div></div><label>Technical specifications (one “Name: Value” per line)</label><textarea name="specs" rows="5">${esc(Object.entries(p.specs).map(([k,v])=>`${k}: ${v}`).join('\n'))}</textarea><label>Material notes</label><textarea name="material" rows="2">${esc(p.material)}</textarea><label>Design tips & tolerances</label><textarea name="tips" rows="2">${esc(p.tips)}</textarea><label>Connections</label><div class="connections-picker">${project.parts.filter(x=>add||x.id!==p.id).map(x=>`<label><input type="checkbox" name="connections" value="${x.id}" ${p.connections.includes(x.id)?'checked':''}>${esc(x.name)}</label>`).join('')||'<span class="muted">No other components yet.</span>'}</div><div class="modal-footer">${btn('close-modal','CANCEL')}<button class="btn white">${add?'ADD COMPONENT':'SAVE CHANGES'}</button></div></form>`);}
function newProject(){showModal('NEW PROJECT',`<form id="new-project-form" class="modal-form"><label>Project name</label><input name="name" placeholder="What are you building?" required maxlength="100"><label>Start with</label><select name="template"><option value="robot">Autonomous robot · 26 components</option><option value="blank">Blank project</option></select><label>Design brief</label><textarea name="description" placeholder="Describe the purpose, dimensions, and requirements…" rows="4"></textarea><div class="modal-footer">${btn('close-modal','CANCEL')}<button class="btn white">CREATE PROJECT ${icon('arrow')}</button></div></form>`);}
function exportModal(){showModal('EXPORT PROJECT',`<div class="export-options"><button class="export-option" data-action="download-project">${icon('folder')}<span><b>COMPLETE PROJECT</b><small>Portable JSON · components, notes, connections & instructions</small></span>${icon('download')}</button><button class="export-option" data-action="bom">${icon('parts')}<span><b>BILL OF MATERIALS</b><small>CSV · quantities, unit costs & totals</small></span>${icon('download')}</button>${currentPart()?.geometry?`<button class="export-option" data-action="download-scad">${icon('cube')}<span><b>PARAMETRIC CAD</b><small>Editable OpenSCAD source for ${esc(currentPart().name)}</small></span>${icon('download')}</button><button class="export-option" data-action="download-stl">${icon('cube')}<span><b>3D MESH</b><small>STL bracket geometry for ${esc(currentPart().name)}</small></span>${icon('download')}</button>`:''}</div>`);}
function download(url){const a=document.createElement('a');a.href=url;a.download='';a.click();toast('Your export is downloading.');}
async function downloadCAD(format){const p=currentPart();if(!p?.geometry)throw new Error('Select a component with parametric geometry first.');if(readOnly){toast('Fork this snapshot to export its CAD.');return;}download(`/api/projects/${project.id}/parts/${p.id}/cad?format=${format}`);}
async function sharing(publishOnly=false){if(readOnly)return;showModal('PUBLISH & SHARE',`<p class="share-info">Publish a read-only snapshot of your parts, specifications, connections, and build guide. Private chat and design history are excluded.</p><p class="modal-hint">This installation runs on your machine. Links work in browsers that can reach this server; they stay on this installation.</p>${project.published?`<label class="eyebrow">READ-ONLY LINK</label><div class="share-link"><input id="share-url" readonly value="${esc(location.origin+'/shared/'+project.published)}">${btn('copy-link','COPY','white','copy')}</div><div class="modal-footer">${btn('unpublish','UNPUBLISH','danger')}${btn('republish','UPDATE SNAPSHOT','white','globe')}</div>`:`<div class="modal-footer">${btn('close-modal','CANCEL')}${btn('republish',publishOnly?'PUBLISH PROJECT':'CREATE SHARE LINK','green','globe')}</div>`}`);}
function settings(){showModal(`${icon('settings')} WORKSPACE SETTINGS`,`<div class="open-source-note">All implemented features are unlocked for everyone. No subscriptions, plans, trials, credits, or application usage quotas. Use your own installed models for local inference.</div><div class="integration-row"><div><strong>Active model</strong><small>${esc(session.label||'Local commands')} · ${esc(session.provider)}</small></div>${btn('models','SWITCH MODEL','white','mech')}</div><p class="modal-hint">Installed Ollama models run on your machine without provider API charges. Optional commercial providers use your own account and may charge for inference; this app does not unlock their services.</p><div class="integration-row"><div><strong>Collect all the details</strong><small>Images → observations, components, unknowns & questions</small></div>${btn('upload','UPLOAD IMAGE','','image')}</div><p class="modal-hint">Select a vision-capable local model for image collection. A photograph cannot establish hidden specifications or engineering verification.</p><div class="integration-row"><div><strong>Millwright / SolidWorks</strong><small>${session.millwright?'Sidecar configured':'Optional Windows CAD bridge'}</small></div>${btn('millwright','CHECK CONNECTION','','link')}</div><p class="modal-hint">Optional provider keys and integration paths remain in blueprint/.env; they are never exported to the browser.</p><div class="modal-footer">${btn('profile','EDIT PROFILE','','users')}${btn('close-modal','DONE','white')}</div>`);}

async function millwright(){showModal('SOLIDWORKS CONNECTION','<p class="modal-hint"><span class="spinner"></span> Checking Millwright…</p>');const status=await api('/millwright/status');showModal('SOLIDWORKS CONNECTION',`<div class="integration-row"><div><strong>Millwright sidecar</strong><small>${esc(status.error||(!status.configured?'Not configured':status.connected?'Connected to SolidWorks':'Sidecar available; SolidWorks is not attached'))}</small></div><span class="status-pill ${status.connected?'online':''}">${status.connected?'Connected':status.configured?'Available':'Offline'}</span></div>${status.tools?`<p class="modal-hint">${status.tools.length} modeling and inspection tools discovered. This web workspace exposes connection inspection only; use the configured Millwright MCP client for direct SolidWorks operations.</p>`:'<pre class="code-block">MILLWRIGHT_SIDECAR=D:\\Millwright-master\\Millwright-master\\sidecar\nPYTHON=python</pre><p class="modal-hint">Add these settings to blueprint/.env and restart Blue Design. Open SolidWorks before attaching to a document.</p>'}<div class="modal-footer">${btn('millwright','RECHECK','','mech')}${btn('close-modal','DONE','white')}</div>`);}
function historyModal(){showModal('PROJECT HISTORY',`<ol class="history-list">${project.history.map(h=>`<li><strong>${esc(h.title)}</strong><small>${new Date(h.at).toLocaleString()}</small></li>`).join('')||'<li>No history is included in this snapshot.</li>'}</ol>`);}
function profileModal(){showModal('YOUR WORKSPACE',`<form class="modal-form" id="profile-form"><label>Display name</label><input name="name" value="${esc(session.profile.name)}" maxlength="80" required><label>Email label (optional)</label><input name="email" type="email" value="${esc(session.profile.email)}" maxlength="160"><p class="modal-hint">This is a local profile label, not a cloud account. No email is sent.</p><div class="modal-footer">${btn('close-modal','CANCEL')}<button class="btn white">SAVE PROFILE</button></div></form>`);}
const actions={home,projects:()=>collection('projects'),community:()=>collection('community'),'new-project':newProject,'close-modal':closeModal,settings,profile:profileModal,models:modelSelector,history:historyModal,'add-part':()=>partEditor(true),'edit-part':()=>partEditor(false),export:exportModal,share:()=>sharing(false),publish:()=>sharing(true),millwright,
 'back-parts':()=>{tab='Parts';detail=false;renderEditor();},
 'collapse-chat':()=>{const editor=$('.editor');editor.classList.toggle('chat-collapsed');if(editor.classList.contains('chat-collapsed')){const b=document.createElement('button');b.className='restore-chat';b.dataset.action='collapse-chat';b.ariaLabel='Show chat';b.innerHTML=icon('chat');editor.append(b);}else $('.restore-chat')?.remove();},
 'toggle-suggestions':()=>{const el=$('.suggestions');el.hidden=!el.hidden;},
 'clear-chat':()=>{if(readOnly)return;showModal('CLEAR CONVERSATION',`<p class="share-info">Remove the messages in this project? Components, parameters, and build progress will remain.</p><div class="modal-footer">${btn('close-modal','CANCEL')}${btn('confirm-clear','CLEAR MESSAGES','white')}</div>`);},
 'confirm-clear':async()=>{await mutate('chat',{},'DELETE');closeModal();renderEditor();},
 'delete-part':()=>{if(readOnly)return;showModal('REMOVE COMPONENT',`<p class="share-info">Remove ${esc(currentPart().name)} and its incoming connections? You can add the component again from Parts.</p><div class="modal-footer">${btn('close-modal','CANCEL')}${btn('confirm-delete','REMOVE','danger')}</div>`);},
 'confirm-delete':async()=>{await mutate(`parts/${currentPart().id}`,{},'DELETE');partId=project.parts[0]?.id;detail=false;closeModal();renderEditor();},
 'download-project':()=>download(`/api/projects/${project.id}/export`),bom:()=>{if(readOnly)return toast('Fork this project to export the bill of materials.');download(`/api/projects/${project.id}/bom`);},
 'download-scad':()=>downloadCAD('scad'),'download-stl':()=>downloadCAD('stl'),
 cad:()=>{tab='Mech';renderEditor();toast('Parametric geometry ready. Drag to inspect or export your model.');},
 duplicate:async()=>{const copy=await api(`/projects/${project.id}/duplicate`,{method:'POST',body:{}});await refreshProjects();await openProject(copy.id);toast('Project duplicated.');},
 fork:async()=>{const copy=await api('/import',{method:'POST',body:{project}});await refreshProjects();await openProject(copy.id);toast('Snapshot forked into your projects.');},
 republish:async()=>{const result=await api(`/projects/${project.id}/publish`,{method:'POST',body:{}});project=result.project;await refreshProjects();renderEditor();sharing();toast('Read-only snapshot published on this installation.');},
 unpublish:async()=>{await mutate('publish',{},'DELETE');closeModal();renderEditor();toast('Share link revoked.');},
 'analyze-source':analyzeSource,'regenerate-guide':regenerateGuide,'copy-link':async()=>{try{await navigator.clipboard.writeText($('#share-url').value);toast('Read-only project link copied.');}catch{$('#share-url').select();toast('Select and copy the link shown.');}},
 import:()=>$('#import-file').click(),upload:uploadModal,'choose-source':()=>$('#source-file').click(),
 'mcp-connect':async()=>{const c=await api('/mcp');const config={mcpServers:{blue_design:{command:c.command,args:c.args,env:c.env}}};const toml='[mcp_servers.blue_design]\ncommand = '+JSON.stringify(c.command)+'\nargs = '+JSON.stringify(c.args)+'\n\n[mcp_servers.blue_design.env]\nBLUE_DESIGN_URL = '+JSON.stringify(c.env.BLUE_DESIGN_URL);showModal('CONNECT BLUE DESIGN VIA MCP',`<div class="mcp-connect-info"><p>Use Codex, Claude Desktop, Cursor, or another client that supports local MCP servers to work on this workspace. Keep Blue Design running; saved tool changes appear here automatically.</p><h3>Codex configuration</h3><textarea readonly rows="7" aria-label="Codex MCP configuration">${esc(toml)}</textarea><h3>Claude Desktop / Cursor configuration</h3><textarea readonly rows="11" aria-label="MCP JSON configuration">${esc(JSON.stringify(config,null,2))}</textarea><p><b>Workflow:</b> list projects → read project → apply workflow. The connected client supplies the plan directly; no second AI subscription is needed in Blue Design.</p><p class="muted">This is a local stdio connection. Hosted ChatGPT clients require a supported remote connector or tunnel; pasting localhost into a cloud connector will not connect to this computer.</p><p class="muted">Blender and SolidWorks use their own MCP servers. Blue Design provides its project data and assembly layout; it does not execute arbitrary Blender scripts.</p></div><div class="modal-footer">${btn('close-modal','DONE','white')}</div>`);},
 about:()=>showModal(`${logo()} BLUE DESIGN`,`<div class="open-source-note">An independent, self-hosted hardware design workspace inspired by the interface you referenced. Built for your own hardware projects.</div><p class="share-info">Create projects, manage components, track connections, write assembly guides, and export parametric CAD. Your project data stays on your machine.</p><p class="modal-hint">MIT-licensed original code. No proprietary source or model weights are redistributed. Run your own models; all application features are available to everyone.</p><div class="modal-footer">${btn('close-modal','BACK TO BUILDING','white')}</div>`),
 ideas:()=>{const el=$('[name=idea]');el.value='Design an autonomous service robot for indoor deliveries';el.focus();},
 'idea-robot':()=>{const el=$('[name=idea]');el.value='Autonomous service robot';el.focus();},
 'idea-mount':()=>{const el=$('[name=idea]');el.value='Custom motor mount';el.focus();},
 'edit-instructions':()=>{showModal('EDIT BUILD GUIDE',`<form class="modal-form" id="instructions-form"><p class="modal-hint">One step per block: title on the first line, description below. Separate steps with a blank line.</p><textarea name="steps" rows="16">${esc(project.instructions.map(s=>s.title+'\n'+s.body).join('\n\n'))}</textarea><div class="modal-footer">${btn('close-modal','CANCEL')}<button class="btn white">SAVE GUIDE</button></div></form>`);}
};
document.addEventListener('click',async e=>{const button=e.target.closest('button,a[data-action]');if(!button)return;try{
 if(button.dataset.action){const fn=actions[button.dataset.action];if(fn){e.preventDefault();await fn();}}
 else if(button.dataset.groupCheck&&!readOnly){const instructions=structuredClone(project.instructions),steps=instructions.filter(s=>(s.group||'Assemble')===button.dataset.groupCheck),done=!steps.every(s=>s.done);steps.forEach(s=>s.done=done);await mutate('instructions',{instructions},'PUT');renderEditor();}
 else if(button.dataset.workflowTab){tab=button.dataset.workflowTab;if(tab==='Parts')detail=false;renderEditor();}
 else if(button.dataset.project)await openProject(button.dataset.project);
 else if(button.dataset.shared)await openShared(button.dataset.shared);
 else if(button.dataset.tab){tab=button.dataset.tab;if(tab==='Mech'&&!currentPart()?.geometry)partId=project.parts.find(p=>p.geometry)?.id||partId;renderEditor();}
 else if(button.dataset.part){partId=button.dataset.part;tab='Parts';detail=true;renderEditor();$('.workspace').scrollTop=0;}
 else if(button.dataset.modelIndex){const choice=modelChoices[Number(button.dataset.modelIndex)-1];if(choice){const selected=await api('/models',{method:'PATCH',body:{provider:choice.provider,model:choice.model}});Object.assign(session,selected);closeModal();if(page==='editor')renderEditor();else if(page==='home')home();else await collection(page);toast('Active model: '+selected.label);}}
 else if(button.dataset.geometry){partId=button.dataset.geometry;renderEditor();}
 else if(button.dataset.filter){filter=button.dataset.filter;$('#content').innerHTML=partsList();}
 else if(button.dataset.mode){mode=button.dataset.mode;$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('#chat-input').placeholder=mode==='Ask'?'> Ask about your design…':'> Describe a change to apply…';}
 else if(button.dataset.suggest){$('#chat-input').value=button.dataset.suggest;$('#chat-input').focus();}
 }catch(error){if(modal.open)errorInModal(error);else toast(error.message);}});
document.addEventListener('input',e=>{if(e.target.id==='part-search'){const selection=e.target.selectionStart;query=e.target.value;$('#content').innerHTML=partsList();const field=$('#part-search');field.focus();field.setSelectionRange(selection,selection);}});
document.addEventListener('change',async e=>{if(e.target.dataset.step){try{const instructions=structuredClone(project.instructions);instructions.find(s=>s.id===e.target.dataset.step).done=e.target.checked;await mutate('instructions',{instructions},'PUT');renderEditor();}catch(error){toast(error.message);e.target.checked=!e.target.checked;}}});
document.addEventListener('keydown',e=>{if(e.target.id==='chat-input'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#chat-form').requestSubmit();}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();if(project){tab='Parts';detail=false;renderEditor();$('#part-search').focus();}else $('[name=idea]')?.focus();}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,fields=new FormData(form);const submit=form.querySelector('button:not([type=button]):not([data-action])');if(submit)submit.disabled=true;try{
 if(form.id==='create-prompt'){const idea=String(fields.get('idea')).trim();if(!idea)return;const isRobot=/robot|rover|service/i.test(idea),isMount=/mount|bracket/i.test(idea);const created=await api('/projects',{method:'POST',body:{name:idea.length>70?idea.slice(0,67)+'…':idea,description:idea,template:isRobot||isMount?'robot':'blank'}});await refreshProjects();await openProject(created.id);if(isMount){tab='Mech';renderEditor();}else if(!isRobot){tab='Info';renderEditor();toast('Project created. Add components or connect an AI provider to develop your design.');}else toast('Robot project created from the editable robot template.');}
 else if(form.id==='new-project-form'){const p=await api('/projects',{method:'POST',body:Object.fromEntries(fields)});await refreshProjects();closeModal();await openProject(p.id);if(!p.parts.length){detail=false;renderEditor();}}
 else if(form.id==='chat-form'){if(sending||readOnly)return;const text=String(fields.get('text')).trim();if(!text)return;sending=true;$('#chat-input').value='';$('#messages').innerHTML=renderMessages().replace('<div class="thinking">Working on your design…</div>','')+`<article class="message user">${esc(text)}</article>${mode==='Edit'?workflowPending():'<div class="thinking">Answering your question…</div>'}`;$('#messages').scrollTop=$('#messages').scrollHeight;$('.chat-send').disabled=true;let failure;try{await mutate('chat',{text,mode,partId});}catch(error){failure=error;}finally{sending=false;renderEditor();}if(failure){$('#chat-input').value=text;throw failure;}}
 else if(form.id==='part-form'){const raw=Object.fromEntries(fields);raw.quantity=Number(raw.quantity);raw.cost=Number(raw.cost);const specs={};for(const line of raw.specs.split('\n').filter(l=>l.trim())){const i=line.indexOf(':');if(i<1)throw new Error('Write specifications as Name: Value, one per line.');specs[line.slice(0,i).trim()]=line.slice(i+1).trim();}raw.specs=specs;raw.connections=fields.getAll('connections');raw.geometry=raw.geometry==='bracket'?(form.dataset.add==='false'?currentPart()?.geometry:null)||{kind:'bracket',width:80,depth:65,height:75,wall:4,hole:36}:null;if(form.dataset.add==='true'){await mutate('parts',raw);partId=project.parts.at(-1).id;}else await mutate(`parts/${currentPart().id}`,raw,'PATCH');detail=true;tab='Parts';closeModal();renderEditor();toast('Component saved.');}
 else if(form.id==='wire-form'){await saveWireForm(form,fields);}
 else if(form.id==='layout-form'){const parts=structuredClone(project.assembly.parts),item=parts.find(p=>p.partId===form.dataset.part);for(const k of ['x','y','z','width','depth','height'])item[k]=Number(fields.get(k));item.estimated=true;await mutate('assembly',{parts},'PUT');closeModal();renderEditor();toast('Assembly layout saved.');}
 else if(form.id==='geometry-form'){const geometry={kind:'bracket',...Object.fromEntries([...fields].map(([k,v])=>[k,Number(v)]))};await mutate(`parts/${currentPart().id}`,{geometry,specs:{...currentPart().specs,'Wall Thickness':geometry.wall+'mm'}},'PATCH');closeModal();renderEditor();toast('Model updated. CAD exports use the saved dimensions.');}
 else if(form.id==='project-form'){project=await api(`/projects/${project.id}`,{method:'PATCH',body:{...Object.fromEntries(fields),version:project.version}});await refreshProjects();renderEditor();toast('Project settings saved.');}
 else if(form.id==='instructions-form'){const blocks=String(fields.get('steps')).trim().split(/\n\s*\n/).filter(Boolean);const instructions=blocks.map((block,i)=>{const [title,...rest]=block.split('\n');return {...(project.instructions[i]||{}),id:project.instructions[i]?.id,title,body:rest.join('\n'),done:!!project.instructions[i]?.done};});await mutate('instructions',{instructions},'PUT');closeModal();renderEditor();toast('Assembly guide saved.');}
 else if(form.id==='model-form'){const selected=await api('/models',{method:'PATCH',body:Object.fromEntries(fields)});Object.assign(session,selected);closeModal();if(page==='editor')renderEditor();else if(page==='home')home();else await collection(page);toast('Active model: '+selected.label);}
 else if(form.id==='profile-form'){session.profile=await api('/profile',{method:'PATCH',body:Object.fromEntries(fields)});closeModal();if(page==='editor')renderEditor();else if(page==='home')home();else await collection(page);toast('Workspace profile saved.');}
 }catch(error){if(modal.open)errorInModal(error);else toast(error.message);}finally{if(submit?.isConnected)submit.disabled=false;}});
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('Project files must be smaller than 2MB');const data=JSON.parse(await file.text());const p=await api('/import',{method:'POST',body:{project:data.project||data}});await refreshProjects();closeModal();await openProject(p.id);toast('Project imported.');}catch(error){toast(error.message);}finally{e.target.value='';}};
modal.addEventListener('click',e=>{if(e.target===modal){const rect=modal.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
async function boot(){try{session=await api('/session');const shared=location.pathname.match(/^\/shared\/([a-f0-9]+)$/);if(shared)return await openShared(shared[1]);await refreshProjects();const id=new URLSearchParams(location.search).get('project');if(id&&projects.some(p=>p.id===id))return await openProject(id);home();}catch(e){app.innerHTML=`<div class="error-card"><h1>COULDN’T OPEN WORKSPACE</h1><p>${esc(e.message)}</p><p>Start Blue Design with <code>npm start</code> from the blueprint folder, then open the URL printed in your terminal.</p><a class="btn white" href="/">TRY AGAIN</a></div>`;}}
function costTable(){const totals={};for(const p of project.parts){const c=['ELECTRONICS','POWER','SENSOR'].includes(p.category)?'Electrical':'Mechanical';totals[c]||={count:0,cost:0};totals[c].count+=p.quantity;totals[c].cost+=p.quantity*p.cost;}return `<table class="cost-table"><thead><tr><th>CATEGORY</th><th>PARTS</th><th>COST</th></tr></thead><tbody>${Object.entries(totals).map(([name,v])=>`<tr><td>${name}</td><td>${v.count}</td><td>${v.cost>0?'$'+v.cost.toFixed(2):'Not specified'}</td></tr>`).join('')}<tr class="total"><td>Total</td><td>${project.parts.reduce((s,p)=>s+p.quantity,0)}</td><td>${cost()>0?'$'+cost().toFixed(2):'Not specified'}</td></tr></tbody></table>`;}
function aboutSidebar(){return `<div class="panel-title"><span>${icon('info')} ABOUT</span><button class="plain" data-action="upload" title="Upload content">${icon('plus')}</button></div><div class="about-sidebar"><div class="project-keywords"><span>${project.parts.length} PARTS</span><span>${project.parts.filter(p=>p.geometry).length} CAD MODELS</span><span>COMPONENTS & SPECIFICATIONS</span><span>ASSEMBLY GUIDE</span></div><h3>${esc(project.name.toUpperCase())}</h3><p>${esc(project.description)}</p>${costTable()}<div class="source-label">SOURCE FILES</div>${(project.uploads||[]).map(u=>`<a class="source-chip" href="/api/projects/${project.id}/uploads/${u.id}" target="_blank" rel="noopener">${icon(u.mime.startsWith('image/')?'image':'file')}<span>${esc(u.name)}<small>${(u.size/1024).toFixed(1)} KB</small></span>${icon('external')}</a>`).join('')||'<p class="muted">Upload a brief, image, or bill of materials to ground your design.</p>'}</div><div class="about-sidebar-footer">${btn('upload','UPLOAD CONTENT','','image')}${btn('duplicate','COPY TO MY PROJECTS','white','copy')}</div>`;}
function infoView(){const image=project.uploads?.find(u=>u.mime.startsWith('image/'));return `<div class="overview-layout"><article class="overview-document">${image?`<div class="overview-image"><img src="/api/projects/${project.id}/uploads/${image.id}" alt="${esc(project.name)} — uploaded reference"></div>`:`<div class="overview-image illustration">${robotArt()}<span>PROJECT ILLUSTRATION · UPLOAD YOUR OWN REFERENCE</span></div>`}<div class="overview-title"><h1>${esc(project.name.toUpperCase())}</h1>${!readOnly?`<button class="plain" data-action="project-settings" title="Edit project details">${icon('edit')}</button>`:''}</div><div class="project-keywords"><span>${project.parts.length} COMPONENTS</span><span>HARDWARE DESIGN</span><span>COMPREHENSIVE INSTRUCTIONS</span><span>ASSEMBLY PROCEDURE</span></div><h4 class="eyebrow">PROJECT DESCRIPTION</h4><p class="overview-description">${esc(project.description)}</p>${detailsView()}${costTable()}<div class="overview-section"><h3>DESIGN RESOURCES</h3><div class="resource-links">${btn('back-parts','PARTS & SPECIFICATIONS','','parts')}${btn('view-instructions','BUILD GUIDE','','file')}${btn('view-mech','MECHANICAL DESIGN','','cube')}</div></div>${!project.parts.length?`<div class="open-source-note">Your source content is saved. ${session.provider==='local'?'Upload a CSV BOM, add components, or choose a local vision model to collect details from your image.':'Use Collect all the details to extract components from your uploaded reference.'}</div>`:''}${!readOnly?`<div class="overview-section">${btn('upload','ADD SOURCE CONTENT','','image')}${project.uploads?.length?btn('analyze-source','COLLECT ALL THE DETAILS','white','bolt'):''}</div>`:''}</article><aside class="overview-parts"><div class="overview-parts-title">${icon('parts')} PARTS LIST <span>${project.parts.length}</span></div>${project.parts.map(p=>`<button data-part="${p.id}" class="overview-part"><span class="part-category-dot ${p.category.toLowerCase()}"></span><span>${esc(p.name)}</span><small>${p.quantity>1?(p.quantityStatus==='estimated'||project.details?'≈ ×':'×')+p.quantity:''}</small></button>`).join('')}${!project.parts.length?'<p class="modal-hint">Components extracted from your content will appear here.</p>':''}${!readOnly?btn('add-part','ADD COMPONENT','','plus'):''}</aside></div>`;}
actions['project-settings']=()=>showModal('PROJECT DETAILS',`<form class="modal-form" id="project-form"><label>Project name</label><input name="name" value="${esc(project.name)}" required maxlength="100"><label>Design brief</label><textarea name="description" rows="8" maxlength="5000">${esc(project.description)}</textarea><div class="modal-footer">${btn('close-modal','CANCEL')}<button class="btn white">SAVE DETAILS</button></div></form>`);
actions['view-instructions']=()=>{tab='Instructions';renderEditor();};actions['view-mech']=()=>{tab='Mech';partId=project.parts.find(p=>p.geometry)?.id;renderEditor();};
function uploadModal(){if(readOnly)return toast('Fork this project to upload source content.');showModal('UPLOAD YOUR CONTENT',`<button class="upload-drop" data-action="choose-source">${icon('image')}<strong>Bring your idea into Blue Design</strong><span>Choose an image, document, or bill of materials</span><small>PNG, JPEG, WebP, PDF, TXT, Markdown, CSV · up to 8MB</small></button><p class="modal-hint">${project?'Files will be attached to this project.':'A new project will be created for your uploaded content.'} You can inspect the source before extracting components.</p><div class="open-source-note">CSV and text work locally. Images work with an installed Ollama vision model. Optional remote providers require your own credentials. Only clicking Collect all the details sends the selected file to the active model.</div><p class="modal-hint">CSV columns: <code>Name, Category, Quantity, Cost, Description</code><br>Markdown part records: <code>- [part] Motor | ELECTRONICS | 2 | 32 | 12V DC</code></p><div class="modal-footer">${btn('import','IMPORT PROJECT JSON','','folder')}${btn('choose-source','CHOOSE FILE','white','plus')}</div>`);}
$('#source-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>8*1024*1024)throw new Error('Source files must be 8MB or smaller.');if(!project){project=await api('/projects',{method:'POST',body:{name:file.name.replace(/\.[^.]+$/,''),template:'blank',description:'Project created from uploaded source content. Collect all the details to extract the design.'}});await refreshProjects();}showModal('UPLOADING CONTENT','<p class="modal-hint"><span class="spinner"></span> Saving your source file…</p>');const buffer=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<buffer.length;i+=8192)binary+=String.fromCharCode(...buffer.subarray(i,i+8192));const result=await api(`/projects/${project.id}/uploads`,{method:'POST',body:{name:file.name,data:btoa(binary),version:project.version}});project=result.project;await refreshProjects();readOnly=false;page='editor';tab='Info';history.replaceState(null,'',`/?project=${project.id}`);closeModal();renderEditor();showModal('CONTENT UPLOADED',`<p class="share-info"><b>${esc(file.name)}</b> is saved in your project. Build a structured project with a description, parts list, costs, and assembly steps.</p><p class="modal-hint">${/\.(csv|txt|md)$/i.test(file.name)?'This file can be parsed locally. CSV rows become editable components. Text is preserved as your design brief; explicit [part] records become components.':'Your selected vision model collects visible features and components. Unknown dimensions and prices remain unspecified. Local Ollama models keep this file on your machine.'}</p><div class="modal-footer">${btn('close-modal','VIEW PROJECT')}${btn('analyze-source','COLLECT ALL THE DETAILS','white','bolt')}</div>`);}catch(error){if(modal.open)errorInModal(error);else toast(error.message);}finally{e.target.value='';}};
async function analyzeSource(){const source=project.uploads?.findLast(u=>!u.analyzedAt)||project.uploads?.at(-1);if(!source)return uploadModal();if(source.analyzedAt)return toast('This source has already been processed. Upload a new revision to add more components.');if(!source.mime.startsWith('text/')&&session.provider==='local'){await modelSelector();return toast('Choose a vision model, then collect the image details.');}showModal('COLLECTING ALL THE DETAILS',`<p class="modal-hint"><span class="spinner"></span> Inspecting ${esc(source.name)} with ${esc(session.label||session.provider)}. Local models may take a few minutes…</p>`);try{project=await api(`/projects/${project.id}/uploads/${source.id}/analyze`,{method:'POST',body:{version:project.version}});await refreshProjects();tab='Info';closeModal();renderEditor();toast('Details collected. Review observed features and unknown specifications.');}catch(error){errorInModal(error);}}
async function mountEngineering(){const root=$('#engineering-root');if(!root)return;const openingTab=tab;try{if(openingTab==='Wiring'){const data=project.wiring||await api(`/projects/${project.id}/wiring`);if(!root.isConnected)return;project.wiring=data;disposeViewer=mountWiring(root,{project,data,readOnly,onPart:id=>{partId=id;tab='Parts';detail=true;renderEditor();},onSave:async wiring=>{await mutate('wiring',{wiring},'PUT');},onWire:wireEditor,onEnrich:async()=>{if(readOnly)return toast('Fork this project to enrich its wiring.');await mutate('wiring');renderEditor();toast('Wiring rebuilt from component relationships. Pin assignments remain unverified.');}});}else{const data=project.assembly||await api(`/projects/${project.id}/assembly`);if(!root.isConnected)return;project.assembly=data;disposeViewer=mountAssembly(root,{project,data,readOnly,onPart:id=>{partId=id;tab='Parts';detail=true;renderEditor();},onSave:async parts=>{await mutate('assembly',{parts},'PUT');},onRebuild:async()=>{if(readOnly)return toast('Fork this project to edit the layout.');await mutate('assembly');renderEditor();toast('Conceptual layout rebuilt. Estimated envelopes need real dimensions.');},onCAD:openCAD,onEdit:layoutEditor});}}catch(error){if(root.isConnected)root.innerHTML=`<div class="error-card">${esc(error.message)}</div>`;}}
function wireEditor(edge,data){if(readOnly)return;project.wiring=data;showModal(edge?'EDIT CONNECTION':'ADD CONNECTION',`<form id="wire-form" class="modal-form" data-edge="${esc(edge?.id||'')}"><p class="modal-hint">Define a conceptual connection. Confirm actual pins, voltage ratings and ground topology from the component datasheets.</p><div class="form-grid"><div><label>From component</label><select name="from">${data.nodes.map(n=>`<option value="${n.partId}" ${n.partId===edge?.from?'selected':''}>${esc(project.parts.find(p=>p.id===n.partId)?.name)}</option>`).join('')}</select></div><div><label>To component</label><select name="to">${data.nodes.map(n=>`<option value="${n.partId}" ${n.partId===edge?.to?'selected':''}>${esc(project.parts.find(p=>p.id===n.partId)?.name)}</option>`).join('')}</select></div></div><label>Connection type</label><select name="type">${['data','power','ground'].map(t=>`<option ${edge?.type===t?'selected':''}>${t}</option>`).join('')}</select><label>Signal / supply</label><input name="signal" value="${esc(edge?.signal||'Interface TBD')}" maxlength="150"><div class="form-grid"><div><label>Source pin / port</label><input name="fromPort" value="${esc(edge?.fromPort||'TBD')}" maxlength="80"></div><div><label>Destination pin / port</label><input name="toPort" value="${esc(edge?.toPort||'TBD')}" maxlength="80"></div></div><div class="modal-footer">${edge?`<button type="button" class="btn danger" data-action="delete-wire" data-edge-id="${esc(edge.id)}">DELETE CONNECTION</button>`:''}${btn('close-modal','CANCEL')}<button class="btn white">SAVE CONNECTION</button></div></form>`);}
async function saveWireForm(form,fields){const wiring=structuredClone(project.wiring),edge=Object.fromEntries(fields);edge.id=form.dataset.edge||crypto.randomUUID();if(form.dataset.edge)wiring.edges=wiring.edges.map(e=>e.id===edge.id?edge:e);else wiring.edges.push(edge);await mutate('wiring',{wiring},'PUT');closeModal();renderEditor();toast('Connection saved.');}
actions['delete-wire']=async()=>{const edge=$('#wire-form').dataset.edge,wiring=structuredClone(project.wiring);wiring.edges=wiring.edges.filter(e=>e.id!==edge);await mutate('wiring',{wiring},'PUT');closeModal();renderEditor();};
function layoutEditor(item){if(readOnly)return toast('Fork this project to edit its layout.');showModal('COMPONENT LAYOUT',`<form class="modal-form" id="layout-form" data-part="${item.partId}"><p class="modal-hint">${esc(project.parts.find(p=>p.id===item.partId)?.name)} · Layout envelopes are estimates until you supply physical measurements. Editing an envelope does not modify the underlying part CAD.</p><div class="dimension-grid">${[['x','Position X'],['y','Position Y'],['z','Position Z'],['width','Width'],['depth','Depth'],['height','Height']].map(([key,label])=>`<label>${label} (mm)<input name="${key}" type="number" step="0.1" value="${item[key]}" required></label>`).join('')}</div><div class="modal-footer">${btn('close-modal','CANCEL')}<button class="btn white">SAVE LAYOUT</button></div></form>`);}
function openCAD(id){partId=id;const part=currentPart();if(!part?.geometry){showModal('ASSEMBLY CAD',`<p class="share-info">Export the current assembly layout as editable OpenSCAD envelopes. Estimated component shapes are layout references, not manufacturing models.</p><div class="modal-footer">${btn('close-modal','CANCEL')}${btn('export-assembly','EXPORT LAYOUT SCAD','white','download')}</div>`);return;}showModal('PARAMETRIC CAD',`<div class="mech-viewer"><canvas id="part-cad-preview" aria-label="Interactive parametric part preview"></canvas></div><form id="geometry-form" class="modal-form"><div class="dimension-grid">${[['width','Width'],['depth','Depth'],['height','Height'],['wall','Wall thickness'],['hole','Motor hole diameter']].map(([key,label])=>`<label>${label} (mm)<input name="${key}" type="number" value="${part.geometry[key]}" step="0.1" min="1" max="500" required ${readOnly?'disabled':''}></label>`).join('')}</div><div class="modal-footer">${btn('download-scad','EXPORT SCAD','','download')}${btn('download-stl','EXPORT STL','','download')}${!readOnly?'<button class="btn white">UPDATE MODEL</button>':''}</div></form>`);modalViewerDispose=mountViewer($('#part-cad-preview'),part.geometry);}
actions['export-assembly']=()=>download(`/api/projects/${project.id}/assembly/export`);
async function regenerateGuide(){if(readOnly)return;await mutate('instructions/generate');renderEditor();toast('13 build steps generated from the current component list.');}
let modelChoices=[];
async function modelSelector(){showModal('CHOOSE YOUR MODEL','<p class="modal-hint"><span class="spinner"></span> Discovering installed models…</p>');try{const catalog=await api('/models');modelChoices=catalog.models;showModal('CHOOSE YOUR MODEL',`<div class="open-source-note">All features are available with every model. No plans or upgrade steps. Local inference uses your own hardware.</div><div class="model-list">${catalog.models.map((m,i)=>`<button class="model-choice ${session.provider===m.provider&&session.model===m.model?'active':''}" data-model-index="${i+1}"><span class="model-symbol">${icon(m.local?'cube':'globe')}</span><span><strong>${esc(m.label)}</strong><small>${esc(m.description)}</small></span><span class="model-badge">${m.provider==='local'?'OFFLINE':m.local?'LOCAL':'YOUR PROVIDER'}</span>${session.provider===m.provider&&session.model===m.model?icon('check'):''}</button>`).join('')}</div>${catalog.issues.map(i=>`<p class="modal-hint">${esc(i)}</p>`).join('')}<details class="model-help"><summary>Use another local model</summary><p class="modal-hint">Install a model in Ollama, then refresh this list. For image collection, choose a vision-capable model. Model licenses and hardware requirements vary.</p><pre class="code-block">ollama list\nollama pull &lt;model-name&gt;</pre></details>${catalog.openaiConfigured?`<form id="model-form" class="modal-form"><input name="provider" type="hidden" value="openai"><label>Custom model ID from your provider</label><input name="model" placeholder="Enter a model ID" required maxlength="180"><div class="modal-footer"><button class="btn">USE PROVIDER MODEL</button></div></form>`:''}<div class="modal-footer">${btn('models','REFRESH','','mech')}${btn('close-modal','DONE','white')}</div>`);}catch(error){errorInModal(error);}}
function detailsView(){const d=project.details;if(!d)return `<section class="collected-details"><div class="details-heading"><h3>COLLECT ALL THE DETAILS</h3>${project.uploads?.length&&!readOnly?btn('analyze-source','COLLECT DETAILS','white','search'):''}</div><p class="modal-hint">Upload an image and choose a vision model to collect visible features, a component list, unknown specifications, and follow-up questions.</p></section>`;return `<section class="collected-details"><div class="details-heading"><h3>COLLECT ALL THE DETAILS</h3><span class="status-pill">${esc(d.provider)}</span></div><p class="details-caption">Source-based review · ${new Date(d.collectedAt).toLocaleDateString()} · Verify AI-extracted counts and engineering details</p><div class="detail-findings">${[['observed','VISIBLE IN THE IMAGE','check'],['inferred','INFERRED / PROPOSED SYSTEMS','bulb'],['unknown','DETAILS TO CONFIRM','search'],['questions','QUESTIONS FOR YOUR BUILD','chat']].map(([key,title,i])=>`<div class="finding-group ${key}"><h4>${icon(i)}${title}</h4><ul>${(d[key]||[]).map(t=>`<li>${esc(t)}</li>`).join('')||'<li>No details recorded.</li>'}</ul></div>`).join('')}</div></section>`;}
boot();

// Observe externally saved changes without replacing unsent forms or active drags.
let syncInFlight=false,pointerBusy=false;
document.addEventListener('pointerdown',()=>pointerBusy=true);document.addEventListener('pointerup',()=>pointerBusy=false);window.addEventListener('blur',()=>pointerBusy=false);
setInterval(async()=>{if(syncInFlight||sending||readOnly||modal.open||pointerBusy||document.visibilityState!=='visible'||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||$('#chat-input')?.value.trim()||$('[name=idea]')?.value.trim())return;syncInFlight=true;try{if(page==='editor'&&project){const atId=project.id,atVersion=project.version;const revision=await api(`/projects/${atId}/revision`);if(project?.id===atId&&revision.version!==atVersion&&!sending&&!modal.open&&!$('#chat-input')?.value.trim()){const next=await api(`/projects/${atId}`);if(project?.id!==atId||project.version!==atVersion||sending||modal.open||pointerBusy||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||$('#chat-input')?.value.trim())return;project=next;await refreshProjects();renderEditor();toast(next.workflow?.provider==='MCP client'?'MCP workflow synchronized.':'Project changes synchronized.');}}else if(page==='home'){const next=await api('/projects');if(page==='home'&&!$('[name=idea]')?.value.trim()&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&JSON.stringify(next)!==JSON.stringify(projects)){projects=next;home();}}}catch{/* A disconnected preview must not discard local form input. */}finally{syncInFlight=false;}},2500);
